mapper.select:
select h.id,h.hazard_no as title,h.status,h.create_time as createTime,
       h.requirements as reason,'SAME_TARGET_CONTEXT' as basis
from lab_hazard h join lab_device d on d.id=#{deviceId} and d.del_flag='0'
where h.del_flag='0'
  and ((h.target_type='DEVICE' and h.target_id=d.id)
    or (h.target_type='LABORATORY' and h.target_id=d.laboratory_id))
  and (h.owner_id=#{viewerId}

    or 1=1

      or d.laboratory_id in #{id}

  )
order by h.create_time desc,h.id desc limit #{limit}

select (select count(1) from lab_qualification q where q.user_id=#{applicantId} and q.del_flag='0' and q.revoked_at is null and q.valid_from <= #{at} and #{at} < q.valid_until and q.laboratory_id=d.laboratory_id and ((q.scope_type='LABORATORY' and binary q.scope_id=binary cast(d.laboratory_id as char)) or (q.scope_type='DEVICE_CATEGORY' and q.scope_id=d.category_code))) from lab_device d where d.id=#{deviceId} and d.del_flag='0' and (#{applicantId}=#{viewerId}
or 1=1
or d.laboratory_id in #{id}
)
